        public String name() {
            return 'public-test-inner';
        }
    }

    private static List<Object> describeRows(List<ApexTypeImplementor> rows) {
        List<Object> described = new List<Object>();
        for (ApexTypeImplementor row : rows) {
            described.add(new Map<String, Object>{
                'ClassName' => row.ClassName,
                'ClassNamespacePrefix' => row.ClassNamespacePrefix,
                'InterfaceName' => row.InterfaceName,
                'InterfaceNamespacePrefix' => row.InterfaceNamespacePrefix,
                'IsConcrete' => row.IsConcrete
            });
        }
        return described;
    }

    @IsTest
    static void observe() {
        Map<String, Object> payload = new Map<String, Object>{
            'route' => 'named',
            'sourceApi' => 67,
            'helperApi' => 67
        };
        Type matchingType = Type.forName('GlyphFixtures.Matching');
        payload.put('matchingTypeExists', matchingType != null);
        payload.put('matchingTypeText', matchingType == null ? null : String.valueOf(matchingType));

        List<ApexTypeImplementor> interfaceRows = [
            SELECT ClassName, ClassNamespacePrefix, InterfaceName,
                   InterfaceNamespacePrefix, IsConcrete
            FROM ApexTypeImplementor
            WHERE InterfaceName = 'AtlasContract'
            ORDER BY ClassName, ClassNamespacePrefix
        ];
        payload.put('interfaceRows', describeRows(interfaceRows));

        List<ApexTypeImplementor> scalarRows = [
            SELECT ClassName, ClassNamespacePrefix, InterfaceName,
                   InterfaceNamespacePrefix, IsConcrete
            FROM ApexTypeImplementor
            WHERE ClassName IN ('Matching', 'GlyphFixtures.Matching')
              AND ClassNamespacePrefix IN ('GlyphFixtures', '')
              AND InterfaceName = 'AtlasContract'
            WITH SYSTEM_MODE
            ORDER BY ClassName, ClassNamespacePrefix
        ];
        List<String> scalarNames = new List<String>();
        for (ApexTypeImplementor row : scalarRows) { scalarNames.add(row.ClassName); }
        payload.put('scalarNames', scalarNames);

        Set<String> classNames = new Set<String>{'Matching', 'GlyphFixtures.Matching'};
        Set<String> namespacePrefixes = new Set<String>{'GlyphFixtures', ''};
        List<ApexTypeImplementor> boundRows = [
            SELECT ClassName, ClassNamespacePrefix, InterfaceName,
                   InterfaceNamespacePrefix, IsConcrete
            FROM ApexTypeImplementor
            WHERE ClassName IN :classNames
              AND ClassNamespacePrefix IN :namespacePrefixes
              AND InterfaceName = 'AtlasContract'
            WITH SYSTEM_MODE
            ORDER BY ClassName, ClassNamespacePrefix
        ];
        List<String> boundNames = new List<String>();
        for (ApexTypeImplementor row : boundRows) { boundNames.add(row.ClassName); }
        payload.put('boundNames', boundNames);
        payload.put('namespaceNullCount', [
            SELECT COUNT()
            FROM ApexTypeImplementor
            WHERE InterfaceName = 'AtlasContract' AND ClassNamespacePrefix = null
            WITH SYSTEM_MODE
        ]);
        payload.put('namespaceEmptyCount', [
            SELECT COUNT()
            FROM ApexTypeImplementor
            WHERE InterfaceName = 'AtlasContract' AND ClassNamespacePrefix = ''
            WITH SYSTEM_MODE
        ]);
        payload.put('unrelatedCount', [
            SELECT COUNT()
            FROM ApexTypeImplementor
            WHERE InterfaceName = 'AtlasContract' AND ClassName = 'AtlasPlain'
            WITH SYSTEM_MODE
        ]);
        System.assert(false, 'IMPLEMENTOR_OBSERVATION|' + JSON.serialize(payload));
